<?php
require_once dirname(__DIR__,2).'/app/views.php'; require_once dirname(__DIR__,2).'/app/bookings.php'; require_role(['staff','admin']); $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try { change_booking(integer_input('id',1,PHP_INT_MAX),text_input('status',1,20)); flash('Booking status updated.'); go('/staff/bookings.php'); } catch (InvalidArgumentException $ex) {$error=$ex->getMessage();} }
$status=is_string($_GET['status']??null)?$_GET['status']:''; $params=[]; $where='';
if (in_array($status,['pending','confirmed','cancelled','completed'],true)) { $where=' WHERE b.status=?'; $params[]=$status; }
$bookings=sql('SELECT b.*,u.name,u.email FROM bookings b JOIN users u ON u.id=b.user_id'.$where.' ORDER BY b.id DESC',$params)->fetchAll();
page_start('Manage bookings'); heading('STAFF WORKSPACE','Every journey starts here.'); ?>
<section class="container pb-5"><?php dashboard_nav('Bookings'); error_box($error); ?><form method="get" class="d-flex gap-2 mb-4 align-items-end"><div><label class="form-label" for="status">Booking status</label><select class="form-select" name="status" id="status"><option value="">All statuses</option><?php foreach (['pending','confirmed','cancelled','completed'] as $s): ?><option value="<?= $s ?>" <?= $s===$status?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Filter</button></form><div class="surface table-responsive"><table class="table align-middle"><thead><tr><th>Booking / traveller</th><th>Adventure</th><th>Date / guests</th><th>Total</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach ($bookings as $b): ?><tr><td><strong>GT-<?= str_pad((string)$b['id'],5,'0',STR_PAD_LEFT) ?></strong><br><?= e($b['name']) ?><br><small><?= e($b['email']) ?></small></td><td><?= e($b['package_title']) ?></td><td><?= e($b['travel_date']) ?><br><?= (int)$b['travellers'] ?> travellers</td><td><?= money($b['total_cents']) ?></td><td><?= status_badge($b['status']) ?></td><td><?php $next=['pending'=>['confirmed','cancelled'],'confirmed'=>['completed','cancelled']][$b['status']]??[]; if ($next): ?><form class="d-flex gap-2" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$b['id'] ?>"><select class="form-select form-select-sm" name="status" aria-label="New status for booking <?= (int)$b['id'] ?>"><?php foreach ($next as $s): ?><option value="<?= $s ?>"><?= ucfirst($s) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-dark">Save</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php if (!$bookings): ?><p>No bookings match this filter.</p><?php endif; ?></div></section>
<?php page_end(); ?>
